#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long c;
    cin >> n >> c;
    vector<long long> x(n);
    for (int i = 0; i < n; i++) cin >> x[i];

    sort(x.begin(), x.end());
    long long lo = 1, hi = x[n - 1] - x[0];
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2, count = 1, last = x[0];
        for (int i = 1; i < n; i++) {
            if (x[i] - last >= mid) {
                count++;
                last = x[i];
            }
        }
        if (count >= c) lo = mid;
        else hi = mid - 1;
    }
    cout << lo << "\n";

    return 0;
}

