import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long c = Long.parseLong(next());
        long[] x = new long[(int) n];
        for (int i = 0; i < x.length; i++) x[i] = Long.parseLong(next());

        Arrays.sort(x);
        long lo = 1, hi = x[(int) n - 1] - x[0];
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2, count = 1, last = x[0];
            for (int i = 1; i < n; i++) {
                if (x[i] - last >= mid) {
                    count++;
                    last = x[i];
                }
            }
            if (count >= c) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }
}
